package it.comune.trieste.ouf.onboarding.application;

import com.fasterxml.jackson.databind.ObjectMapper;
import it.comune.trieste.ouf.onboarding.domain.*;
import java.sql.Types;
import java.time.*;
import java.util.*;
import org.springframework.http.HttpStatus;
import org.springframework.jdbc.core.SqlParameterValue;
import org.springframework.jdbc.core.simple.JdbcClient;
import org.springframework.stereotype.Service;
import org.springframework.transaction.support.TransactionTemplate;

@Service
public class ManagedFileService {
  private static final long MAX_PROFILE_BYTES=10L*1024*1024;
  private final JdbcClient db; private final ObjectMapper json; private final CanonicalHash hashes; private final ManagedFileProfiler profiler; private final TransactionTemplate tx; private final OnboardingService onboarding;
  public ManagedFileService(JdbcClient db,ObjectMapper json,CanonicalHash hashes,ManagedFileProfiler profiler,TransactionTemplate tx,OnboardingService onboarding){this.db=db;this.json=json;this.hashes=hashes;this.profiler=profiler;this.tx=tx;this.onboarding=onboarding;}
  public Map<String,Object> register(String sourceId,String stagingRef,String contentHash,String mediaType,long size,String uploadedBy,String retentionRef){
    if(!stagingRef.startsWith("object://"))throw invalid("ONB_STAGING_REF_INVALID","stagingRef must use object://");if(size<1||size>MAX_PROFILE_BYTES)throw invalid("ONB_FILE_SIZE_INVALID","File exceeds the 10 MiB deterministic profiling limit");UUID id=UUID.randomUUID();
    return tx.execute(status->{db.sql("insert into ouf_onboarding.managed_file_asset(asset_id,source_id,staging_ref,content_hash,media_type,size_bytes,uploaded_by,retention_ref) values(:i,:s,:r,:h,:m,:z,:u,:x) on conflict(staging_ref,content_hash) do nothing").param("i",id).param("s",new SqlParameterValue(Types.VARCHAR,sourceId)).param("r",stagingRef).param("h",contentHash).param("m",mediaType).param("z",size).param("u",uploadedBy).param("x",retentionRef).update();return db.sql("select asset_id,source_id,staging_ref,content_hash,media_type,size_bytes,uploaded_by,retention_ref,status,created_at from ouf_onboarding.managed_file_asset where staging_ref=:r and content_hash=:h").param("r",stagingRef).param("h",contentHash).query().singleRow();});
  }
  public Map<String,Object> profile(UUID assetId,byte[] bytes,String sampleRef){
    Map<String,Object> asset=asset(assetId);if(((Number)asset.get("size_bytes")).longValue()!=bytes.length)throw invalid("ONB_FILE_SIZE_MISMATCH","Staged size does not match downloaded content");String actual=hashes.ofBytes(bytes);if(!actual.equals(asset.get("content_hash")))throw invalid("ONB_FILE_HASH_MISMATCH","Staged content hash does not match downloaded content");ManagedFileProfiler.Profile result=profiler.profile(bytes,String.valueOf(asset.get("media_type")));
    return tx.execute(status->{db.sql("select 1 as acquired from pg_advisory_xact_lock(hashtextextended(:i,0))").param("i",assetId.toString()).query(Integer.class).single();int version=db.sql("select coalesce(max(version),0)+1 from ouf_onboarding.file_profile where asset_id=:a").param("a",assetId).query(Integer.class).single();UUID profileId=UUID.randomUUID();db.sql("insert into ouf_onboarding.file_profile(profile_id,asset_id,version,format,metadata,inferred_schema,candidate_keys,sample_ref,redacted_sample) values(:i,:a,:v,:f,cast(:m as jsonb),cast(:s as jsonb),cast(:k as jsonb),:r,cast(:q as jsonb))").param("i",profileId).param("a",assetId).param("v",version).param("f",result.format()).param("m",write(result.metadata())).param("s",write(result.columns())).param("k",write(result.candidateKeys())).param("r",sampleRef).param("q",write(result.sample())).update();db.sql("update ouf_onboarding.managed_file_asset set status='PROFILED' where asset_id=:a and status in ('STAGED','PROFILED')").param("a",assetId).update();return fileProfile(assetId,profileId);});
  }
  public Map<String,Object> requestProfile(UUID assetId,String idempotencyKey){
    asset(assetId);if(idempotencyKey==null||idempotencyKey.isBlank())throw invalid("ONB_IDEMPOTENCY_KEY_REQUIRED","Idempotency-Key must not be blank");UUID jobId=UUID.randomUUID();
    return tx.execute(status->{db.sql("insert into ouf_onboarding.file_profile_job(job_id,asset_id,idempotency_key) values(:i,:a,:k) on conflict(asset_id,idempotency_key) do nothing").param("i",jobId).param("a",assetId).param("k",idempotencyKey).update();return jobView(db.sql("select job_id,asset_id,idempotency_key,state,attempts,claimed_by,lease_until,next_attempt_at,profile_id,error_code,last_error,created_at,updated_at,completed_at from ouf_onboarding.file_profile_job where asset_id=:a and idempotency_key=:k").param("a",assetId).param("k",idempotencyKey).query().singleRow());});
  }
  public Map<String,Object> profileJob(UUID assetId,UUID jobId){
    return jobView(db.sql("select job_id,asset_id,idempotency_key,state,attempts,claimed_by,lease_until,next_attempt_at,profile_id,error_code,last_error,created_at,updated_at,completed_at from ouf_onboarding.file_profile_job where asset_id=:a and job_id=:i").param("a",assetId).param("i",jobId).query().listOfRows().stream().findFirst().orElseThrow(()->new DomainFailure(HttpStatus.NOT_FOUND,"ONB_FILE_PROFILE_JOB_NOT_FOUND","File profile job not found")));
  }
  public Optional<Map<String,Object>> claimProfile(String worker,Duration lease,Instant now){
    return tx.execute(status->{requireLease(lease);OffsetDateTime instant=utc(now);db.sql("update ouf_onboarding.file_profile_job set state='FAILED',claimed_by=null,lease_until=null,error_code='ONB_PROFILE_LEASE_EXHAUSTED',last_error='Lease expired after maximum attempts',completed_at=:n,updated_at=:n where state='RUNNING' and lease_until<=:n and attempts>=5").param("n",instant).update();List<Map<String,Object>> claimed=db.sql("with candidate as (select job_id from ouf_onboarding.file_profile_job where ((state in ('READY','RETRY_WAIT') and next_attempt_at<=:n) or (state='RUNNING' and lease_until<=:n)) and attempts<5 order by next_attempt_at,created_at for update skip locked limit 1) update ouf_onboarding.file_profile_job j set state='RUNNING',claimed_by=:w,lease_until=:u,attempts=j.attempts+1,error_code=null,last_error=null,updated_at=:n where j.job_id=(select job_id from candidate) returning j.*").param("n",instant).param("w",worker).param("u",utc(now.plus(lease))).query().listOfRows();return claimed.stream().findFirst().map(row->{Map<String,Object> out=new LinkedHashMap<>(row);out.putAll(asset((UUID)row.get("asset_id")));return out;});});
  }
  public Map<String,Object> completeProfile(UUID jobId,String worker,byte[] bytes,String sampleRef){
    return tx.execute(status->{Map<String,Object> job=db.sql("select job_id,asset_id,state,claimed_by,lease_until from ouf_onboarding.file_profile_job where job_id=:i for update").param("i",jobId).query().singleRow();if(!"RUNNING".equals(job.get("state"))||!worker.equals(job.get("claimed_by")))throw conflict("ONB_FILE_PROFILE_JOB_CONFLICT","Profile job is not owned by this worker");Map<String,Object> result=profile((UUID)job.get("asset_id"),bytes,sampleRef);int changed=db.sql("update ouf_onboarding.file_profile_job set state='SUCCEEDED',profile_id=:p,claimed_by=null,lease_until=null,completed_at=transaction_timestamp(),updated_at=transaction_timestamp() where job_id=:i and state='RUNNING' and claimed_by=:w and lease_until>transaction_timestamp()").param("p",result.get("profile_id")).param("i",jobId).param("w",worker).update();if(changed!=1)throw conflict("ONB_FILE_PROFILE_JOB_CONFLICT","Profile job lease was lost");return profileJob((UUID)job.get("asset_id"),jobId);});
  }
  public Map<String,Object> failProfile(UUID jobId,String worker,String errorCode,String detail,Duration retryAfter){
    return tx.execute(status->{if(retryAfter.isNegative())throw invalid("ONB_RETRY_DELAY_INVALID","retryAfter must not be negative");Map<String,Object> row=db.sql("select asset_id,attempts from ouf_onboarding.file_profile_job where job_id=:i").param("i",jobId).query().singleRow();int changed=db.sql("update ouf_onboarding.file_profile_job set state=case when attempts>=5 then 'FAILED' else 'RETRY_WAIT' end,claimed_by=null,lease_until=null,next_attempt_at=transaction_timestamp()+make_interval(secs=>:r),error_code=:e,last_error=:d,completed_at=case when attempts>=5 then transaction_timestamp() else null end,updated_at=transaction_timestamp() where job_id=:i and state='RUNNING' and claimed_by=:w and lease_until>transaction_timestamp()").param("r",retryAfter.toSeconds()).param("e",errorCode).param("d",safe(detail)).param("i",jobId).param("w",worker).update();if(changed!=1)throw conflict("ONB_FILE_PROFILE_JOB_CONFLICT","Profile job is not owned by this worker");if(((Number)row.get("attempts")).intValue()>=5)quarantine((UUID)row.get("asset_id"),jobId,errorCode,safe(detail),"profile-job:"+jobId);return profileJob((UUID)row.get("asset_id"),jobId);});
  }
  public List<Map<String,Object>> quarantines(String state){String selected=state==null?"OPEN":state;if(!Set.of("OPEN","RELEASED","REJECTED").contains(selected))throw invalid("ONB_QUARANTINE_STATE_INVALID","Unsupported quarantine state");return db.sql("select quarantine_id,asset_id,profile_job_id,reason_code,evidence_ref,safe_detail,state,created_at,resolved_at,resolved_by_subject,correlation_id from ouf_onboarding.managed_file_quarantine where state=:s order by created_at desc").param("s",selected).query().listOfRows();}
  public Map<String,Object> quarantine(UUID id){return db.sql("select quarantine_id,asset_id,profile_job_id,reason_code,evidence_ref,safe_detail,state,created_at,resolved_at,resolved_by_subject,correlation_id from ouf_onboarding.managed_file_quarantine where quarantine_id=:i").param("i",id).query().listOfRows().stream().findFirst().orElseThrow(()->new DomainFailure(HttpStatus.NOT_FOUND,"ONB_QUARANTINE_NOT_FOUND","Managed-file quarantine item not found"));}
  public Map<String,Object> resolveQuarantine(UUID id,String decision,OnboardingService.Actor actor,String authorizationContext,String correlation){if(!"HUMAN_USER".equals(actor.type()))throw new DomainFailure(HttpStatus.FORBIDDEN,"THS_HUMAN_USER_REQUIRED","Quarantine remediation requires HUMAN_USER");String capability="RELEASED".equals(decision)?"ouf.onboarding.quarantine.release":"ouf.onboarding.quarantine.reject";if(!actor.capabilities().contains(capability))throw new DomainFailure(HttpStatus.FORBIDDEN,"ONB_QUARANTINE_CAPABILITY_REQUIRED","Authorization did not grant "+capability);return tx.execute(s->{Map<String,Object> q=quarantine(id);int n=db.sql("update ouf_onboarding.managed_file_quarantine set state=:d,resolved_at=transaction_timestamp(),resolved_by_subject=:a,authorization_context_ref=:x where quarantine_id=:i and state='OPEN'").param("d",decision).param("a",actor.subject()).param("x",authorizationContext).param("i",id).update();if(n!=1)throw conflict("ONB_QUARANTINE_NOT_OPEN","Quarantine item is not open");if("RELEASED".equals(decision))db.sql("update ouf_onboarding.managed_file_asset set status='STAGED' where asset_id=:a and status='QUARANTINED'").param("a",q.get("asset_id")).update();db.sql("insert into ouf_onboarding.audit_event(audit_event_id,source_id,onboarding_version_id,correlation_id,actor_subject,actor_type,event_type,payload_summary) values(gen_random_uuid(),(select source_id from ouf_onboarding.managed_file_asset where asset_id=:a),null,:c,:s,'HUMAN_USER',:e,jsonb_build_object('quarantineId',:q,'authorizationContextRef',:x))").param("a",q.get("asset_id")).param("c",correlation).param("s",actor.subject()).param("e","MANAGED_FILE_QUARANTINE_"+decision).param("q",id.toString()).param("x",authorizationContext).update();return quarantine(id);});}
  private void quarantine(UUID asset,UUID job,String code,String detail,String correlation){UUID id=UUID.randomUUID();db.sql("insert into ouf_onboarding.managed_file_quarantine(quarantine_id,asset_id,profile_job_id,reason_code,evidence_ref,safe_detail,correlation_id) values(:i,:a,:j,:c,:e,:d,:r) on conflict do nothing").param("i",id).param("a",asset).param("j",job).param("c",code).param("e","quarantine://managed-files/"+asset+"/"+id).param("d",detail).param("r",correlation).update();db.sql("update ouf_onboarding.managed_file_asset set status='QUARANTINED' where asset_id=:a").param("a",asset).update();}
  private static String safe(String value){if(value==null)return null;String redacted=value.replaceAll("(?i)(password|token|secret|authorization)\\s*[=:]\\s*[^\\s,;]+","$1=[REDACTED]");return redacted.length()>512?redacted.substring(0,512):redacted;}
  public Map<String,Object> asset(UUID id){return db.sql("select asset_id,source_id,staging_ref,content_hash,media_type,size_bytes,uploaded_by,retention_ref,status,created_at from ouf_onboarding.managed_file_asset where asset_id=:i").param("i",id).query().listOfRows().stream().findFirst().orElseThrow(()->new DomainFailure(HttpStatus.NOT_FOUND,"ONB_FILE_ASSET_NOT_FOUND","Managed file asset not found"));}
  public Map<String,Object> fileProfile(UUID asset,UUID profile){return jsonRow(db.sql("select profile_id,asset_id,version,format,metadata::text metadata,inferred_schema::text inferred_schema,candidate_keys::text candidate_keys,sample_ref,redacted_sample::text redacted_sample,created_at from ouf_onboarding.file_profile where asset_id=:a and profile_id=:p").param("a",asset).param("p",profile).query().listOfRows().stream().findFirst().orElseThrow(()->new DomainFailure(HttpStatus.NOT_FOUND,"ONB_FILE_PROFILE_NOT_FOUND","File profile not found")),"metadata","inferred_schema","candidate_keys","redacted_sample");}
  public Map<String,Object> preview(UUID assetId,UUID profileId){Map<String,Object> profile=fileProfile(assetId,profileId);@SuppressWarnings("unchecked") List<String> candidates=(List<String>)profile.get("candidate_keys");@SuppressWarnings("unchecked") List<Map<String,Object>> columns=(List<Map<String,Object>>)profile.get("inferred_schema");Map<String,Object> identity=candidates.isEmpty()?Map.of("strategy","MANAGED_DETERMINISTIC","sourceFields",List.of("$managedRowOrdinal"),"normalizationRuleRef","normalization://managed-file/asset-row-ordinal-v1","stabilityLimit","Identity is unique per row inside the immutable asset and changes if rows are reordered"):Map.of("strategy","NATIVE_KEY","sourceFields",List.of(candidates.get(0)),"normalizationRuleRef","normalization://managed-file/native-key-v1","stabilityLimit","Identity remains stable while the proposed key remains stable");Map<String,Object> out=new LinkedHashMap<>();out.put("assetId",assetId);out.put("profileId",profileId);out.put("profileVersion",profile.get("version"));out.put("format",profile.get("format"));out.put("metadata",profile.get("metadata"));out.put("columns",columns);out.put("candidateKeys",candidates);out.put("redactedSample",profile.get("redacted_sample"));out.put("sampleRef",profile.get("sample_ref"));out.put("recordModel","ONE_ROW_ONE_SOURCE_OBJECT");out.put("identityProposal",identity);out.put("proposalStatus","PENDING_HUMAN_REVIEW");return out;}
  public Map<String,Object> onboard(UUID assetId,UUID profileId,String sourceId,String name,String owner,String targetClassIri,List<String> semanticRefs,List<String> sourceObjectKeyFields,OnboardingService.Actor actor,String correlation){
    return tx.execute(status->{Map<String,Object> asset=asset(assetId),profile=fileProfile(assetId,profileId);onboarding.createSource(sourceId,name,"INTERNAL_MANAGED","MANAGED",owner,Map.of("managedFileAssetId",assetId.toString(),"fileProfileId",profileId.toString(),"contentHash",asset.get("content_hash")),actor,correlation);db.sql("update ouf_onboarding.managed_file_asset set source_id=:s where asset_id=:a and source_id is null").param("s",sourceId).param("a",assetId).update();
      @SuppressWarnings("unchecked") List<Map<String,Object>> columns=(List<Map<String,Object>>)profile.get("inferred_schema");List<String> names=columns.stream().map(c->String.valueOf(c.get("name"))).toList();List<String> keys=sourceObjectKeyFields==null?List.of():List.copyOf(sourceObjectKeyFields);if(!names.containsAll(keys))throw invalid("ONB_FILE_IDENTITY_FIELD_INVALID","Every source-object key field must exist in the selected file profile");List<String> identityFields=keys.isEmpty()?List.of("$managedRowOrdinal"):keys;String identityStrategy=keys.isEmpty()?"MANAGED_DETERMINISTIC":keys.size()==1?"NATIVE_KEY":"COMPOSITE_NATIVE_KEY";Map<String,Object> identity=new LinkedHashMap<>();identity.put("strategy",identityStrategy);identity.put("sourceFields",identityFields);identity.put("normalizationRuleRef",keys.isEmpty()?"normalization://managed-file/asset-row-ordinal-v1":"normalization://managed-file/native-key-v1");identity.put("stabilityLimit",keys.isEmpty()?"Identity is unique per row inside the immutable asset and changes if rows are reordered":"Identity remains stable while the approved key fields remain stable");Map<String,Object> sync=Map.of("bootstrap","FULL_SNAPSHOT","incremental","NONE","pageSize",500);Map<String,Object> runtime=new LinkedHashMap<>();runtime.put("mode","MANAGED");runtime.put("recordModel","ONE_ROW_ONE_SOURCE_OBJECT");runtime.put("rowIdentityBasis",keys.isEmpty()?"ASSET_AND_ROW_ORDINAL":"APPROVED_SOURCE_FIELDS");runtime.put("stagingRef",asset.get("staging_ref"));runtime.put("contentHash",asset.get("content_hash"));runtime.put("assetId",assetId.toString());runtime.put("fileProfileId",profileId.toString());Map<String,Object> semanticTarget=semanticTarget(targetClassIri,semanticRefs);Map<String,Object> config=new LinkedHashMap<>();config.put("syncProfile",sync);config.put("sourceObjectIdentityPolicy",identity);config.put("changeRepresentationProfile",Map.of("mode","FULL_SNAPSHOT"));config.put("extractionProfile",Map.of("profileId","file-"+profileId,"version",String.valueOf(profile.get("version")),"sourceId",sourceId,"selection",Map.of("assetId",assetId.toString(),"fileProfileId",profileId.toString()),"projection",Map.of("FILE",names),"sync",sync,"runtime",runtime));config.put("semanticMapping",Map.of("mappingId","sm-"+sourceId,"sourceType",Map.of("sourceId",sourceId,"typeCode","FILE"),"targetClasses",List.of(semanticTarget),"semanticRefs",semanticRefs));config.put("bundle",Map.of("bundleId","bundle-"+sourceId,"bundleVersion","1.0.0","environment","managed","source",Map.of("sourceId",sourceId,"sourceKind","INTERNAL_MANAGED","acquisitionMode","MANAGED"),"schemaRef","profile://managed-files/"+assetId+"/profiles/"+profileId,"createdFromOnboardingVersion","pending","effectiveFrom","1970-01-01T00:00:00Z","checksum","sha256:pending","status","APPROVED","changeRepresentationProfile",Map.of("mode","FULL_SNAPSHOT")));Map<String,Object> draft=onboarding.createVersion(sourceId,config,actor,correlation);Map<String,Object> out=new LinkedHashMap<>(draft);out.put("managedFileAssetId",assetId);out.put("fileProfileId",profileId);out.put("runtimeTrigger","ACTIVE_BUNDLE");return out;});
  }
  private String write(Object value){try{return json.writeValueAsString(value);}catch(Exception e){throw new IllegalArgumentException(e);}}
  private Map<String,Object> jsonRow(Map<String,Object> row,String...fields){try{Map<String,Object> out=new LinkedHashMap<>(row);for(String f:fields)if(out.get(f) instanceof String s)out.put(f,json.readValue(s,Object.class));return out;}catch(Exception e){throw new IllegalStateException(e);}}
  private static DomainFailure invalid(String code,String message){return new DomainFailure(HttpStatus.UNPROCESSABLE_ENTITY,code,message);}
  private static DomainFailure conflict(String code,String message){return new DomainFailure(HttpStatus.CONFLICT,code,message);}
  private static OffsetDateTime utc(Instant instant){return OffsetDateTime.ofInstant(instant,ZoneOffset.UTC);}
  private static void requireLease(Duration lease){if(lease.toSeconds()<10||lease.toSeconds()>3600)throw invalid("ONB_LEASE_INVALID","lease must be between PT10S and PT1H");}
  private static Map<String,Object> semanticTarget(String classIri,List<String> refs){if(refs==null||refs.isEmpty())throw invalid("ONB_SEMANTIC_REF_INVALID","At least one pinned semantic reference is required");String ref=refs.get(0);int at=ref.lastIndexOf('@');if(at<1||at==ref.length()-1)throw invalid("ONB_SEMANTIC_REF_INVALID","Semantic references must pin id@version");return Map.of("ontologyId",ref.substring(0,at),"ontologyVersion",ref.substring(at+1),"classIri",classIri);}
  private static Map<String,Object> jobView(Map<String,Object> row){Map<String,Object> out=new LinkedHashMap<>(row);out.put("jobId",row.get("job_id"));out.put("status","READY".equals(row.get("state"))?"QUEUED":row.get("state"));out.put("createdAt",row.get("created_at"));out.put("updatedAt",row.get("updated_at"));out.put("nextRetryAt",row.get("next_attempt_at"));out.put("resultRef",row.get("profile_id"));out.put("errorCode",row.get("error_code"));return out;}
}
